Given an arr[] of integers and a positive integer k, find the longest subarray's length with the sum of the elements divisible by k.Examples:Input: arr[] = [2, 7, 6, 1, 4, 5], k = 3Output: 4Explanation: The subarray [7, 6, 1, 4] has sum = 18, which is divisible by 3.Input: arr[] = [-2, 2, -5, 12, -11, -1, 7], k = 3Output: 5Explanation: The subarray [2, -5, 12, -11, -1], has sum = -3, which is divisible by 3.Input: arr[] = [1, 2, -2], k = 5Output: 2Explanation: The subarray is [2, -2] with sum = 0, which is divisible by 5.Try It YourselfTable of Content[Naive Approach] - Iterating over all subarrays - O(n^2) Time and O(1) Space[Expected Approach] - Using Prefix Sum modulo k -  O(n) Time and O(min(n, k)) Space[Naive Approach] - Iterating over all subarrays - O(n^2) Time and O(1) SpaceConsider all the subarray sums using two nested for loops and return the length of the longest subarray with a sum divisible by k. To avoid overflow while computing the sum of the subarray, we can keep track of (subarray sum % k) and if (subarray sum % k) results to 0, we can use its length to find the longest subarray divisible by k.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int longestSubarrayDivK(vector<int> &arr, int k) {
    int res = 0;
    for (int i = 0; i < arr.size(); i++) {

        // Initialize sum for the current subarray
        int sum = 0;
        for (int j = i; j < arr.size(); j++) {

            // Add the current element to the subarray sum
            sum = (sum + arr[j]) % k;

            // Update max length if sum is divisible by k
            if (sum == 0)
                res = max(res, j - i + 1);
        }
    }
    return res;
}

int main() {
    vector<int> arr = {2, 7, 6, 1, 4, 5};
    int k = 3;

    cout << longestSubarrayDivK(arr, k);
    return 0;
}


